```zig
const std = @import("std");
const mem = std.mem;

pub const AffineCipherError = error{
    NotCoprime,
};

const m: u32 = 26;

fn gcd(a: u32, b: u32) u32 {
    var x = a;
    var y = b;
    while (y != 0) {
        const t = x % y;
        x = y;
        y = t;
    }
    return x;
}

fn modInverse(a: u32, modulus: u32) ?u32 {
    // find x such that a*x mod modulus == 1
    var x: u32 = 1;
    while (x < modulus) : (x += 1) {
        if ((a * x) % modulus == 1) return x;
    }
    return null;
}

pub fn encode(allocator: mem.Allocator, phrase: []const u8, a: u8, b: u8) (mem.Allocator.Error || AffineCipherError)![]u8 {
    if (gcd(@as(u32, a), m) != 1) return AffineCipherError.NotCoprime;

    // First pass: collect valid characters (letters and digits), letters lowercased
    var cleaned = std.ArrayList(u8).init(allocator);
    defer cleaned.deinit();

    for (phrase) |c| {
        if (std.ascii.isAlphabetic(c)) {
            try cleaned.append(std.ascii.toLower(c));
        } else if (std.ascii.isDigit(c)) {
            try cleaned.append(c);
        }
    }

    // Second pass: encode letters, group in 5s
    var out = std.ArrayList(u8).init(allocator);
    defer out.deinit();

    var count: usize = 0;
    for (cleaned.items) |c| {
        if (count == 5) {
            try out.append(' ');
            count = 0;
        }
        if (std.ascii.isAlphabetic(c)) {
            const i = @as(u32, c - 'a');
            const e = (@as(u32, a) * i + @as(u32, b)) % m;
            try out.append(@intCast('a' + e));
        } else {
            try out.append(c);
        }
        count += 1;
    }

    return out.toOwnedSlice();
}
```

