```zig
const std = @import("std");
const mem = std.mem;

pub const AffineCipherError = error{
    NotCoprime,
};

const modulus: u32 = 26;

fn gcd(a: u32, b: u32) u32 {
    var x = a;
    var y = b;
    while (y != 0) {
        const t = x % y;
        x = y;
        y = t;
    }
    return x;
}

fn modInverse(a: u32, mod: u32) ?u32 {
    var x: u32 = 1;
    while (x < mod) : (x += 1) {
        if ((a % mod) * x % mod == 1) return x;
    }
    return null;
}

pub fn encode(allocator: mem.Allocator, phrase: []const u8, a: u8, b: u8) (mem.Allocator.Error || AffineCipherError)![]u8 {
    if (gcd(@as(u32, a), modulus) != 1) return AffineCipherError.NotCoprime;

    const a32: u32 = a;
    const b32: u32 = b;

    var n: usize = 0;
    for (phrase) |c| {
        if (std.ascii.isAlphabetic(c) or std.ascii.isDigit(c)) n += 1;
    }

    const spaces: usize = if (n == 0) 0 else (n - 1) / 5;
    const out = try allocator.alloc(u8, n + spaces);
    errdefer allocator.free(out);

    var idx: usize = 0;
    var count: usize = 0;
    for (phrase) |c| {
        if (std.ascii.isAlphabetic(c)) {
            if (count == 5) {
                out[idx] = ' ';
                idx += 1;
                count = 0;
            }
            const i: u32 = @as(u32, std.ascii.toLower(c)) - 'a';
            const e = (a32 * i + b32) % modulus;
            out[idx] = @intCast('a' + e);
            idx += 1;
            count += 1;
        } else if (std.ascii.isDigit(c)) {
            if (count == 5) {
                out[idx] = ' ';
                idx += 1;
                count = 0;
            }
            out[idx] = c;
            idx += 1;
            count += 1;
        }
    }

    return out;
}
```

