const std = @import("std");
const mem = std.mem;

pub const AffineCipherError = error{
    NotCoprime,
};

const m: u32 = 26;

fn gcd(a: u32, b: u32) u32 {
    var x = a;
    var y = b;
    while (y != 0) {
        const t = x % y;
        x = y;
        y = t;
    }
    return x;
}

fn modInverse(a: u32, modulus: u32) ?u32 {
    // find x such that a*x mod modulus == 1
    var x: u32 = 1;
    while (x < modulus) : (x += 1) {
        if ((a * x) % modulus == 1) return x;
    }
    return null;
}

pub fn encode(allocator: mem.Allocator, phrase: []const u8, a: u8, b: u8) (mem.Allocator.Error || AffineCipherError)![]u8 {
    if (gcd(@as(u32, a), m) != 1) return AffineCipherError.NotCoprime;

    // First pass: collect valid characters (letters and digits), letters lowercased
    var cleaned = std.ArrayList(u8).init(allocator);
    defer cleaned.deinit();

